        2'd1:    EnArbiter <= AWVALIDsi2mi[1];
        2'd2:    EnArbiter <= AWVALIDsi2mi[2];
        default: EnArbiter <= 1'b0;
    endcase
end

always  @(posedge ACLK or negedge ARESETn)
