    else if((LockArbiter[1] | LockArbiter[5]) & !LockPort[SELMASTER_WID]) // STATE --> FUll_MASK
    begin                                    // STATE --> VMASK
        CtlData2WrchMux <= LockPort[SELMASTER_WID-1:0];
    end
    else if(!EnArbiter && !ReqFull && LockArbiter[0])
    begin
          if(AWVALIDsi2mi[0]) CtlData2WrchMux <= 2'd0;
          else if(AWVALIDsi2mi[1]) CtlData2WrchMux <= 2'd1;
          else if(AWVALIDsi2mi[2]) CtlData2WrchMux <= 2'd2;
    end
