   case({WireEnAWREADYMUXn, CtlData2WrchMux })
   //synopsys parallel_case full_case
        3'd0:   
            begin
                 AWREADYmi2si[0] <= AWREADYs2mi ;
                 AWREADYmi2si[1] <= 1'b0;
                 AWREADYmi2si[2] <= 1'b0;
            end
        3'd1:   
            begin
