    always @(posedge ACLK or negedge ARESETn)
    begin
        if(!ARESETn)
        begin
            rWENn <= 1'b0;
        end
        else if(WVALIDmi2s & WLASTmi2s & WREADYs2mi & NxReqEmpty)
        begin
            rWENn <= 1'b1;
        end
        else if(WVALIDmi2s & WLASTmi2s & WREADYs2mi & !NxReqEmpty)
        begin
            rWENn <= 1'b0;
