             WDATAsi12mi or
             WDATAsi22mi or
             CtlData2DatachMux or
             WENn // Ver 1.2
            )
    begin
        case({WENn, CtlData2DatachMux})
            //synopsys full_case
            3'd0:   WDATAmi2s <= WDATAsi02mi;
            3'd1:   WDATAmi2s <= WDATAsi12mi;
            3'd2:   WDATAmi2s <= WDATAsi22mi;
            default:
                    WDATAmi2s <= 0;
        endcase
    end

    always @(//3
             WSTRBsi02mi or
             WSTRBsi12mi or
             WSTRBsi22mi or
             CtlData2DatachMux or
             WENn // Ver 1.2
            )
    begin
        case({WENn, CtlData2DatachMux})
            //synopsys full_case
            3'd0:   WSTRBmi2s <= WSTRBsi02mi;
            3'd1:   WSTRBmi2s <= WSTRBsi12mi;
            3'd2:   WSTRBmi2s <= WSTRBsi22mi;
            default:
                    WSTRBmi2s <= 0;
        endcase
    end    

    always @(//4
             WLASTsi2mi  or
             CtlData2DatachMux or
             WENn // Ver 1.2
            )
    begin
        case({WENn, CtlData2DatachMux})
            //synopsys full_case
            3'd0:   WLASTmi2s <= WLASTsi2mi[0];
            3'd1:   WLASTmi2s <= WLASTsi2mi[1];
            3'd2:   WLASTmi2s <= WLASTsi2mi[2];
            default:
                    WLASTmi2s <= 1'b0;
        endcase
    end        

    always @(//5
             WVALIDsi2mi or
             CtlData2DatachMux or
             WENn // Ver 1.2
            )
    begin
        case({WENn, CtlData2DatachMux})
            //synopsys full_case
            3'd0:   WVALIDmi2s <= WVALIDsi2mi[0];
            3'd1:   WVALIDmi2s <= WVALIDsi2mi[1];
            3'd2:   WVALIDmi2s <= WVALIDsi2mi[2];
            default:
                    WVALIDmi2s <= 0;
        endcase
    end        
    //_______________________________________________________________


    // Write response Channel Mux Demux
    //_______________________________________________________________
    
    reg    BREADYmi2s; 
    reg    [MASTER_NUM-1:0]BVALIDmi2si;  


    always  @( BIDs2mi[(SELMASTER_WID-1):0] or
               BREADYsi2mi 
             )
    begin
        case(BIDs2mi[(SELMASTER_WID-1):0])
            //synopsys full_case
            2'd0:   BREADYmi2s <= BREADYsi2mi[0];
            2'd1:   BREADYmi2s <= BREADYsi2mi[1];
            2'd2:   BREADYmi2s <= BREADYsi2mi[2];
            default:     BREADYmi2s <= 0;
        endcase
    end
                        
//MUX TYPE 01 was Generated 
always @(BIDs2mi[(SELMASTER_WID-1):0]  or 
         BVALIDs2mi  )
begin

   case(BIDs2mi[(SELMASTER_WID-1):0] )
   //synopsys parallel_case full_case
        2'd0:   
            begin
                 BVALIDmi2si[0] <= BVALIDs2mi ;
                 BVALIDmi2si[1] <= 1'b0;
                 BVALIDmi2si[2] <= 1'b0;
            end
        2'd1:   
            begin
                 BVALIDmi2si[0] <= 1'b0;
                 BVALIDmi2si[1] <= BVALIDs2mi ;
                 BVALIDmi2si[2] <= 1'b0;
            end
        2'd2:   
            begin
                 BVALIDmi2si[0] <= 1'b0;
                 BVALIDmi2si[1] <= 1'b0;
                 BVALIDmi2si[2] <= BVALIDs2mi ;
            end
         default:
            begin
                BVALIDmi2si[0] <= 1'b0;
                BVALIDmi2si[1] <= 1'b0;
                BVALIDmi2si[2] <= 1'b0;
            end
   endcase
end

    //_______________________________________________________________
    
    //Request Interleaving buffer
    //_______________________________________________________________

    wire    AWREADY2ReqInter = (EnAWREADYMUXn | ReqFull) ? 1'b0:AWREADYs2mi;
    SMC_ReqInterBuff 
    U0ReqInterBuff(
        .ACLK       (ACLK),
        .ARESETn    (ARESETn),

        .AWVALID    (AWVALIDmi2s),
        .AWREADY    (AWREADY2ReqInter),
        .MASTERNUM  (CtlData2WrchMux),

        .BVALID     (BVALIDs2mi),
        .BREADY     (BREADYmi2s),
        .CtlData    (CtlData2DatachMux),

        .ReqFull    (ReqFull),
        .ReqEmpty   (ReqEmpty),
        //Ver 1.7 added
        .NxReqEmpty (NxReqEmpty) 
    );

    //_______________________________________________________________


    //Locked access control block
    //_______________________________________________________________
    
SMC_LockCtlWrmi
U0LockCtlWrmi(

        .ACLK(ACLK),
        .ARESETn(ARESETn),

        .ReqIntEmpty(ReadIntEmptyWrmi2Rdmi),
        .DataCntEmptyRdmi2Wrmi(DataCntEmptyRdmi2Wrmi),

        .ALOCK(AWLOCK2s),
        .AVALID(AWVALID2s),
        .OVALID(ARVALID),

        .LockPort(LockPort),

        .Lock_in(Lock2Wrmi),
        .UnLock_in(UnLock2Wrmi),

        .Lock_out(Lock2Rdmi),
        .UnLock_out(UnLock2Rdmi),

        .CtlData(CtlData2WrchMux),
        //WriteChannel mux CtlData2WrchMux
        //ReadChannel  mux CtlData2RdchMux

        .EnAMUXn(EnAWMUXn),
        .EnAREADYMUXn(EnAWREADYMUXn),
        .LockArbiter(LockArbiter)

        );
    //_______________________________________________________________

    
    //MASTER 0
    wire   [MASTERID_WID-1:0]   BIDmi2si0;     
    wire   [BRESP_WID-1:0]      BRESPmi2si0;   
    assign BIDmi2si0 = BIDs2mi[(SLAVEID_WID-1):SELMASTER_WID];   
    assign BRESPmi2si0 = BRESPs2mi;
    
    //MASTER 1
    wire   [MASTERID_WID-1:0]   BIDmi2si1;     
    wire   [BRESP_WID-1:0]      BRESPmi2si1;   
    assign BIDmi2si1 = BIDs2mi[(SLAVEID_WID-1):SELMASTER_WID];   
    assign BRESPmi2si1 = BRESPs2mi;
    
    //MASTER 2
    wire   [MASTERID_WID-1:0]   BIDmi2si2;     
    wire   [BRESP_WID-1:0]      BRESPmi2si2;   
    assign BIDmi2si2 = BIDs2mi[(SLAVEID_WID-1):SELMASTER_WID];   
    assign BRESPmi2si2 = BRESPs2mi;

endmodule
